#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
int main(void) { int p[2]; if (pipe(p)) return 1; printf("read=%d write=%d O_RDONLY=%d O_WRONLY=%d O_RDWR=%d\n", fcntl(p[0], F_GETFL)&O_ACCMODE, fcntl(p[1], F_GETFL)&O_ACCMODE, O_RDONLY, O_WRONLY, O_RDWR); return 0; }
